<?php
declare(strict_types=1);
function totp_secret(): string {$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$out='';for($i=0;$i<32;$i++)$out.=$alphabet[random_int(0,31)];return $out;}
function totp_code(string $secret,int $timestamp): string {
 $alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split(strtoupper($secret))as $c){$n=strpos($alphabet,$c);if($n===false)throw new InvalidArgumentException('Invalid authenticator secret');$bits.=str_pad(decbin($n),5,'0',STR_PAD_LEFT);}$key='';for($i=0;$i+8<=strlen($bits);$i+=8)$key.=chr(bindec(substr($bits,$i,8)));$counter=(int)floor($timestamp/30);$binary=pack('N2',0,$counter);$hash=hash_hmac('sha1',$binary,$key,true);$offset=ord($hash[19])&15;$number=unpack('N',substr($hash,$offset,4))[1]&0x7fffffff;return str_pad((string)($number%1000000),6,'0',STR_PAD_LEFT);
}
function totp_valid(string $secret,string $code): bool {$code=preg_replace('/\s/','',$code);if(!preg_match('/^\d{6}$/',$code))return false;for($offset=-1;$offset<=1;$offset++)if(hash_equals(totp_code($secret,time()+$offset*30),$code))return true;return false;}
function record_device_session(int $uid): void {$token=bin2hex(random_bytes(32));$_SESSION['device_token']=$token;insert('device_sessions',['user_id'=>$uid,'token_hash'=>hash('sha256',$token),'ip_address'=>substr($_SERVER['REMOTE_ADDR']??'CLI',0,64),'user_agent'=>mb_substr((string)($_SERVER['HTTP_USER_AGENT']??'Installer'),0,250),'created_at'=>now(),'last_seen'=>now(),'revoked_at'=>null]);}
function complete_login(array $u): never {session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['auth_version']=(int)$u['auth_version'];$_SESSION['last_seen']=time();unset($_SESSION['csrf'],$_SESSION['pending_mfa']);record_device_session((int)$u['id']);audit('auth.login',(int)$u['id']);go('dashboard');}
function account_security_post(string $path,array $u): never {
 if($path==='/profile/security/setup'){
 if($u['totp_confirmed'])throw new InvalidArgumentException('Two-factor authentication is already enabled.');if(!password_verify((string)($_POST['current_password']??''),$u['password_hash']))throw new InvalidArgumentException('Enter your current password.');$secret=$_SESSION['mfa_setup_secret']??'';if(!$secret||!totp_valid($secret,text_input('code',20)))throw new InvalidArgumentException('The authenticator code is incorrect. Check the clock on your device.');$codes=[];db()->beginTransaction();try{sql('UPDATE users SET totp_secret=?,totp_confirmed=1,auth_version=auth_version+1 WHERE id=?',[encrypt_secret($secret),$u['id']]);sql('DELETE FROM recovery_codes WHERE user_id=?',[$u['id']]);for($i=0;$i<8;$i++){$code=strtoupper(bin2hex(random_bytes(5)));$codes[]=$code;insert('recovery_codes',['user_id'=>$u['id'],'code_hash'=>hash('sha256',$code),'used_at'=>null]);}audit('security.mfa_enabled',(int)$u['id']);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}$_SESSION['auth_version']=(int)$u['auth_version']+1;unset($_SESSION['mfa_setup_secret']);$_SESSION['new_recovery_codes']=$codes;flash('Two-factor authentication enabled. Store your recovery codes safely.');go('profile/security');
 }
 if($path==='/profile/security/disable'){
 rate_limit('mfa-disable:'.$u['id'],8,900);if(!password_verify((string)($_POST['current_password']??''),$u['password_hash'])||!totp_valid(decrypt_value($u['totp_secret']),text_input('code',20)))throw new InvalidArgumentException('The password or authenticator code is incorrect.');if(setting('staff_mfa_required','0')==='1'&&$u['role']!=='citizen')throw new InvalidArgumentException('Staff two-factor authentication is required by workspace policy.');sql('UPDATE users SET totp_secret=NULL,totp_confirmed=0,auth_version=auth_version+1 WHERE id=?',[$u['id']]);sql('DELETE FROM recovery_codes WHERE user_id=?',[$u['id']]);$_SESSION['auth_version']=(int)$u['auth_version']+1;audit('security.mfa_disabled',(int)$u['id']);flash('Two-factor authentication disabled. Other sessions are signed out.');go('profile/security');
 }
 if($path==='/profile/sessions/revoke'){
 $id=(int)($_POST['id']??0);$current=hash('sha256',$_SESSION['device_token']??'');sql('UPDATE device_sessions SET revoked_at=? WHERE id=? AND user_id=? AND token_hash<>?',[now(),$id,$u['id'],$current]);audit('security.session_revoked',$id);flash('Selected session revoked.');go('profile/security');
 }
 abort_page(404,'Account action not found.');
}
function decrypt_value(?string $value): string {$raw=base64_decode($value??'',true);if(!$raw||strlen($raw)<29)return '';return openssl_decrypt(substr($raw,28),'aes-256-gcm',hash('sha256',(string)cfg('app_key'),true),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16))?:'';}
function two_factor_page(): void {
 $pending=$_SESSION['pending_mfa']??[];if(($pending['expires']??0)<time())go('login');$u=row("SELECT * FROM users WHERE id=? AND status='active'",[$pending['user_id']]);if(!$u||(int)$u['auth_version']!==(int)($pending['auth_version']??0))go('login');
 if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();rate_limit('mfa:'.$u['id'],10,900);$code=strtoupper(preg_replace('/[\s-]/','',(string)($_POST['code']??'')));$ok=totp_valid(decrypt_value($u['totp_secret']),$code);if(!$ok&&preg_match('/^[A-F0-9]{10}$/',$code)){$q=sql('UPDATE recovery_codes SET used_at=? WHERE user_id=? AND code_hash=? AND used_at IS NULL',[now(),$u['id'],hash('sha256',$code)]);$ok=$q->rowCount()>0;}if($ok)complete_login($u);flash('The code is invalid or has already been used.','error');go('two-factor');}
 page_start('Verify your sign-in','An extra check to protect your account.');?><div class="auth-wrap panel panel-body"><h2>Authenticator verification</h2><p class="small muted">Enter the six-digit code from your authenticator app, or an unused recovery code.</p><form action="<?=e(url('two-factor'))?>" method="post"><?=csrf_field()?><?php field('code','Authenticator or recovery code','','text','required maxlength="20" autocomplete="one-time-code"');?><button type="submit" class="btn btn-primary">Verify and sign in</button></form></div><?php page_end();
}
function account_security_page(): void {
 $u=require_user();page_start('Account security','Two-factor authentication and active device sessions.','profile/security');$codes=$_SESSION['new_recovery_codes']??[];unset($_SESSION['new_recovery_codes']);if($codes):?><div class="alert alert-warning"><strong>Save these recovery codes now.</strong> Each code can be used once if your authenticator is unavailable.<pre class="diagnostic"><?=e(implode("\n",$codes))?></pre>They will not be displayed again.</div><?php endif;?><div class="grid grid-2"><?php panel_start('Two-factor authentication');if(!$u['totp_confirmed']){$_SESSION['mfa_setup_secret']??=totp_secret();$secret=$_SESSION['mfa_setup_secret'];$uri='otpauth://totp/'.rawurlencode(setting('app_name','CivicFlow').':'.$u['email']).'?secret='.$secret.'&issuer='.rawurlencode(setting('app_name','CivicFlow')).'&algorithm=SHA1&digits=6&period=30';?><p class="small">Add a time-based account in Microsoft Authenticator, Google Authenticator or another TOTP app. Enter the setup key below, or open the authenticator link on your phone.</p><span class="tracking-code mono"><?=e($secret)?></span><a class="small" href="<?=e($uri)?>">Open in an authenticator app</a><form action="<?=e(url('profile/security/setup'))?>" method="post" class="mt"><?=csrf_field()?><?php field('current_password','Current password','','password','required autocomplete="current-password"');field('code','Six-digit authenticator code','','text','required pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"');?><button class="btn btn-primary" type="submit">Enable two-factor authentication</button></form><?php }else{?><p class="alert">Two-factor authentication is enabled.</p><p class="small muted"><?=(int)value('SELECT COUNT(*) FROM recovery_codes WHERE user_id=? AND used_at IS NULL',[$u['id']])?> unused recovery codes remain.</p><form method="post" action="<?=e(url('profile/security/disable'))?>" data-confirm="Disable two-factor authentication for your account?"><?=csrf_field()?><?php field('current_password','Current password','','password','required');field('code','Current authenticator code','','text','required maxlength="6"');?><button class="btn btn-outline" type="submit">Disable two-factor authentication</button></form><?php }panel_end();panel_start('Signed-in devices');$list=rows('SELECT * FROM device_sessions WHERE user_id=? AND revoked_at IS NULL ORDER BY last_seen DESC LIMIT 30',[$u['id']]);$current=hash('sha256',$_SESSION['device_token']??'');foreach($list as $d):?><div class="activity-item"><?=icon('shield')?><div class="grow"><strong class="small"><?=hash_equals($d['token_hash'],$current)?'This session':'Other device session'?></strong><p><?=e($d['user_agent'])?></p><small><?=e($d['ip_address'])?> · Last active <?=e(dates($d['last_seen'],true))?></small></div><?php if(!hash_equals($d['token_hash'],$current)):?><form method="post" action="<?=e(url('profile/sessions/revoke'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$d['id']?>"><button class="btn btn-outline btn-sm" type="submit">Revoke</button></form><?php endif;?></div><?php endforeach;panel_end();?></div><?php page_end();
}
